insert into passages (id, text, difficulty_level, b, active) values
('a4131541-c4d5-4ec5-83fe-a23fa4806145', 'The Peter Principle, first formulated by educator Laurence J. Peter in 1969, holds that in a hierarchical organization, employees tend to be promoted based on their performance in their current role rather than their aptitude for the role to which they are being promoted, with the result that employees eventually rise to a position for which they are poorly suited and in which they remain indefinitely, since further promotion is no longer earned through continued competent performance. Originally presented with a degree of satirical intent, the principle has nonetheless attracted serious empirical attention from economists interested in organizational behavior. A notable study examining sales organizations found that firms which promoted their most successful salespeople into managerial roles often experienced a decline in overall sales performance, since the traits that make someone an excellent individual salesperson, such as personal charisma and a competitive drive, do not necessarily translate into the very different skill set required to manage and motivate a team of subordinates. Some organizations have attempted to address this mismatch by developing parallel career tracks that allow highly skilled individual contributors to advance in seniority, compensation, and prestige without being funneled into management positions for which they may be ill-suited, thereby decoupling professional advancement from supervisory responsibility. Critics of the Peter Principle counter that while the phenomenon undoubtedly occurs in some organizations, framing it as a near-universal law overstates the case, since many organizations do incorporate leadership potential, not merely current performance, into their promotion criteria.', 5, 2.0, true);
insert into questions (id, type, text, passage_id, options, correct_answer, explanation, a, b, c, difficulty_level, created_by, hint, active) values
('5fb764eb-35d4-471e-a5c7-d4dd7c94cef7', 'sentence_completion', 'The ambassador''s carefully hedged statement was a masterclass in ___, conveying just enough to satisfy reporters without committing to anything substantive.', NULL, '[{"id": "d", "text": "obfuscation"}, {"id": "c", "text": "candor"}, {"id": "a", "text": "transparency"}, {"id": "b", "text": "clarity"}]'::jsonb, 0, '{"strategy": "without committing to anything substantive = בלי להתחייב לשום דבר מהותי. איזו אמנות מאפשרת לומר הרבה בלי להתחייב?", "correct_reason": "obfuscation = ערפול/הסתרה. הצהרה מנוסחת בזהירות שמערפלת בכוונה היא אמנות ערפול.", "options_analysis": ["נכון! obfuscation = ערפול — מתאים לניסוח שממעיט בהתחייבות תוך מראית עין של תוכן", "candor = כנות — הפוך מניסוח שנמנע מהתחייבות", "transparency = שקיפות — הפוך מהצהרה מחושבת שנמנעת מלגלות עמדה אמיתית", "clarity = בהירות — הפוך מניסוח מעורפל שנמנע מהתחייבות"]}', 2.02, 2.0, 0.25, 5, 'ai', NULL, true),
('221d1ad5-1344-4be4-8d7d-acaabd9a3b1a', 'sentence_completion', 'The board''s decision to retain the embattled executive, despite mounting evidence of mismanagement, struck many shareholders as an act of ___.', NULL, '[{"id": "d", "text": "transparency"}, {"id": "a", "text": "complicity"}, {"id": "c", "text": "diligence"}, {"id": "b", "text": "accountability"}]'::jsonb, 1, '{"strategy": "despite mounting evidence of mismanagement = למרות ראיות הולכות וגדלות לניהול כושל. איך נתפסת החלטה לשמור מנהל למרות ראיות שליליות?", "correct_reason": "complicity = שותפות לדבר עבירה. שמירה על מנהל למרות ראיות מרשיעות עלולה להיתפס כשותפות.", "options_analysis": ["transparency = שקיפות — לא מתאר תפיסה שלילית של ההחלטה עצמה", "נכון! complicity = שותפות לדבר עבירה — מתאימה לתפיסה שלילית של ההחלטה", "diligence = חריצות — הפוך מהתעלמות מראיות מרשיעות", "accountability = אחריותיות — הפוך מהחלטה שמתעלמת מראיות שליליות"]}', 1.89, 2.0, 0.25, 5, 'ai', NULL, true),
('3b24dbbd-e89f-4149-a01c-0180c7889c0d', 'sentence_completion', 'The philosopher''s argument, though internally consistent, rests on premises that many find ___ upon closer scrutiny.', NULL, '[{"id": "d", "text": "compelling"}, {"id": "b", "text": "sound"}, {"id": "a", "text": "dubious"}, {"id": "c", "text": "persuasive"}]'::jsonb, 2, '{"strategy": "though internally consistent, rests on premises many find = למרות עקביות פנימית, נשען על הנחות שרבים מוצאים. איך נתפסות הנחות שנבדקות מקרוב ונמצאות בעייתיות?", "correct_reason": "dubious = מפוקפקות. הנחות שנמצאות בעייתיות בבדיקה קרובה הן מפוקפקות.", "options_analysis": ["compelling = משכנעות — הפוך מתפיסה ביקורתית בבדיקה קרובה", "sound = איתנות — הפוך מתפיסה ביקורתית בבדיקה קרובה", "נכון! dubious = מפוקפקות — מתאימות לתפיסה ביקורתית בבדיקה קרובה", "persuasive = משכנעות — הפוך מתפיסה ביקורתית בבדיקה קרובה"]}', 1.68, 2.0, 0.25, 5, 'ai', NULL, true),
('37b3bfea-aad8-40f7-8622-3118a0acf709', 'sentence_completion', 'The novel''s protagonist is a study in ___ : capable of extraordinary kindness one moment and shocking cruelty the next.', NULL, '[{"id": "a", "text": "simplicity"}, {"id": "b", "text": "consistency"}, {"id": "c", "text": "predictability"}, {"id": "d", "text": "contradiction"}]'::jsonb, 3, '{"strategy": "capable of...one moment and...the next = מסוגל ל...ברגע אחד ול...ברגע הבא. איזו תכונה מתארת אישיות עם קצוות מנוגדים כאלה?", "correct_reason": "contradiction = סתירה. אישיות שנעה בין קיצוניות טובה לרעה מגלמת סתירה.", "options_analysis": ["simplicity = פשטות — הפוך מאישיות מורכבת עם קצוות מנוגדים", "consistency = עקביות — הפוך מאישיות שנעה בין קצוות מנוגדים", "predictability = צפיות — הפוך מאישיות שנעה בין קצוות בלתי צפויים", "נכון! contradiction = סתירה — מתאימה לאישיות עם קצוות כה מנוגדים"]}', 1.87, 2.0, 0.25, 5, 'ai', NULL, true),
('61777496-7124-455e-a182-2500c8ad080b', 'sentence_completion', 'The senator''s abrupt reversal on the issue, after years of vocal opposition, left constituents wondering whether her earlier stance had been merely ___.', NULL, '[{"id": "d", "text": "expedient"}, {"id": "c", "text": "sincere"}, {"id": "a", "text": "genuine"}, {"id": "b", "text": "principled"}]'::jsonb, 0, '{"strategy": "abrupt reversal...left constituents wondering = תפנית פתאומית...השאירה תושבים תוהים. איזו עמדה קודמת מוטלת בספק כשמישהו מתהפך פתאום?", "correct_reason": "expedient = נוחה/אופורטוניסטית. תפנית פתאומית מעוררת חשד שהעמדה הקודמת הייתה רק נוחה פוליטית, לא באמת.", "options_analysis": ["נכון! expedient = אופורטוניסטית — מתאימה לחשד שהעמדה הקודמת הייתה רק תועלתנית", "sincere = כנה — הפוך מהספק שמעוררת תפנית פתאומית", "genuine = אמיתית — הפוך מהספק שמעוררת תפנית פתאומית", "principled = עקרונית — הפוך מהספק שמעוררת תפנית פתאומית"]}', 1.84, 2.0, 0.25, 5, 'ai', NULL, true),
('1d4e3e20-f5a1-44b2-8720-7bc8e5be7c71', 'sentence_completion', 'The critic accused the film of ___ sentimentality, manipulating audiences'' emotions through cheap, predictable devices rather than earned narrative payoff.', NULL, '[{"id": "c", "text": "subtle"}, {"id": "d", "text": "cloying"}, {"id": "b", "text": "restrained"}, {"id": "a", "text": "earned"}]'::jsonb, 1, '{"strategy": "manipulating emotions through cheap, predictable devices = מניפולציה רגשית באמצעים זולים וצפויים. איזו רגשנות משתמשת באמצעים כאלה?", "correct_reason": "cloying = מתקתקה/מעוררת בחילה. רגשנות שמשתמשת באמצעים זולים ומניפולטיביים היא מתקתקה עד גועל.", "options_analysis": ["subtle = עדינה — הפוך מרגשנות בוטה ומניפולטיבית", "נכון! cloying = מתקתקה — מתאימה לרגשנות מניפולטיבית וזולה", "restrained = מרוסנת — הפוך מרגשנות בוטה ומניפולטיבית", "earned = מוצדקת — הפוך מרגשנות שמבוססת על אמצעים זולים"]}', 1.83, 2.0, 0.25, 5, 'ai', NULL, true),
('eb46c35e-3641-470d-89a8-1b2d29fe9191', 'sentence_completion', 'The corporation''s public relations campaign, ostensibly about environmental responsibility, was widely dismissed as ___ by watchdog groups.', NULL, '[{"id": "b", "text": "transformative"}, {"id": "a", "text": "authentic"}, {"id": "d", "text": "greenwashing"}, {"id": "c", "text": "substantive"}]'::jsonb, 2, '{"strategy": "ostensibly about...widely dismissed = לכאורה על...נדחתה באופן נרחב. איך נקרא מסע יחסי ציבור שנראה סביבתי אך נתפס כלא כן?", "correct_reason": "greenwashing = הלבנה ירוקה. קמפיין שמתחזה לסביבתי אך נתפס כמזויף נקרא הלבנה ירוקה.", "options_analysis": ["transformative = משנה מציאות — הפוך מקמפיין שנדחה כשטחי", "authentic = אותנטי — הפוך מקמפיין שנדחה כלא אמיתי", "נכון! greenwashing = הלבנה ירוקה — מתאים לקמפיין סביבתי שנחשב מזויף", "substantive = מהותי — הפוך מקמפיין שנדחה כלא אמיתי"]}', 1.82, 2.0, 0.25, 5, 'ai', NULL, true),
('b07710f1-e86a-4f31-92e5-b34b6155ad1b', 'sentence_completion', 'The memoir''s unflinching depiction of addiction avoids the ___ that often mars similar works, refusing to either glamorize or moralize.', NULL, '[{"id": "b", "text": "nuance"}, {"id": "d", "text": "restraint"}, {"id": "c", "text": "subtlety"}, {"id": "a", "text": "sensationalism"}]'::jsonb, 3, '{"strategy": "refusing to either glamorize or moralize = מסרב גם להאדיר וגם להטיף מוסר. מאיזו תכונה נמנעים ספרים דומים לרוב שלא נמנעים ממנה?", "correct_reason": "sensationalism = סנסציוניות. ספרים על התמכרות לרוב נופלים לסנסציוניות שהאדרה או הטפה מייצגות.", "options_analysis": ["nuance = ניואנס — הפוך מתכונה שלילית שהספר נמנע ממנה", "restraint = ריסון — הפוך מתכונה שלילית, זה תכונה חיובית שהספר כן מפגין", "subtlety = עדינות — הפוך מתכונה שלילית שהספר נמנע ממנה", "נכון! sensationalism = סנסציוניות — מתאימה לתכונה שלילית שגורמת להאדרה או הטפה"]}', 2.29, 2.0, 0.25, 5, 'ai', NULL, true),
('42bdde18-afa6-43a7-a88f-d3a545ba6160', 'sentence_completion', 'The regime''s promise of reform proved to be little more than ___, designed to placate international critics without altering the underlying power structure.', NULL, '[{"id": "b", "text": "window dressing"}, {"id": "c", "text": "transformation"}, {"id": "a", "text": "substance"}, {"id": "d", "text": "commitment"}]'::jsonb, 0, '{"strategy": "designed to placate...without altering = נועד לפייס...בלי לשנות. איזה סוג הבטחה מפייסת בלי לשנות דבר?", "correct_reason": "window dressing = קישוט חלון/מראית עין. הבטחת רפורמה שרק מפייסת בלי לשנות היא מראית עין בלבד.", "options_analysis": ["נכון! window dressing = מראית עין — מתאים להבטחה שרק מפייסת בלי שינוי אמיתי", "transformation = שינוי מהותי — הפוך מהבטחה ריקה שאינה משנה מבנה", "substance = תוכן ממשי — הפוך מהבטחה שרק מפייסת בלי לשנות דבר", "commitment = מחויבות — הפוך מהבטחה ריקה מתוכן"]}', 1.9, 2.0, 0.25, 5, 'ai', NULL, true),
('1613782c-3c67-41ca-ac14-09be2526ae56', 'sentence_completion', 'The scholar''s ___ prose, dense with jargon and convoluted syntax, alienated the general readership her publisher had hoped to attract.', NULL, '[{"id": "d", "text": "accessible"}, {"id": "a", "text": "impenetrable"}, {"id": "c", "text": "engaging"}, {"id": "b", "text": "lucid"}]'::jsonb, 1, '{"strategy": "alienated the general readership = ניכרה את קהל הקוראים הכללי. איזה סגנון פרוזה מרחיק קוראים כלליים?", "correct_reason": "impenetrable = בלתי חדיר. פרוזה כבדה ומסובכת שמרחיקה קוראים היא בלתי חדירה.", "options_analysis": ["accessible = נגיש — הפוך מסגנון שמרחיק קוראים", "נכון! impenetrable = בלתי חדיר — מתאים לסגנון כבד שמרחיק קוראים כלליים", "engaging = מרתק — הפוך מסגנון שמרחיק קוראים", "lucid = בהיר — הפוך מסגנון שמרחיק קוראים"]}', 2.09, 2.0, 0.25, 5, 'ai', NULL, true),
('a5f48254-3dbe-4921-a7bf-0be4c81985bf', 'sentence_completion', 'The whistleblower''s testimony, though damaging to her own career, was widely praised for its ___ in exposing wrongdoing at personal cost.', NULL, '[{"id": "b", "text": "self-interest"}, {"id": "d", "text": "cowardice"}, {"id": "a", "text": "integrity"}, {"id": "c", "text": "opportunism"}]'::jsonb, 2, '{"strategy": "though damaging to her own career, widely praised = למרות פגיעה בקריירה שלה, זכתה לשבחים נרחבים. איזו תכונה מוערכת כשמישהו חושף עוול במחיר אישי?", "correct_reason": "integrity = יושרה. חשיפת עוול במחיר אישי מעידה על יושרה.", "options_analysis": ["self-interest = אינטרס עצמי — הפוך מפעולה שפגעה בקריירה של המחברת", "cowardice = פחדנות — הפוך מפעולה שכרוכה בסיכון אישי ומעוררת שבחים", "נכון! integrity = יושרה — מתאימה לפעולה שכרוכה בהקרבה אישית למען חשיפת האמת", "opportunism = אופורטוניזם — הפוך מפעולה שפגעה בקריירה"]}', 2.15, 2.0, 0.25, 5, 'ai', NULL, true),
('d0564d48-61d9-494e-9576-db1924a4d298', 'sentence_completion', 'The committee''s report, while ostensibly neutral, betrayed a subtle ___ toward the interests of the industry it was meant to regulate.', NULL, '[{"id": "d", "text": "objectivity"}, {"id": "a", "text": "hostility"}, {"id": "b", "text": "impartiality"}, {"id": "c", "text": "bias"}]'::jsonb, 3, '{"strategy": "while ostensibly neutral, betrayed = בעוד לכאורה ניטרלי, בגד ב-. איזו תכונה נסתרת מתגלה מתחת למראית עין של נייטרליות?", "correct_reason": "bias = הטיה. דוח שלכאורה ניטרלי אך מגלה נטייה נסתרת חושף הטיה.", "options_analysis": ["objectivity = אובייקטיביות — הפוך מ''betrayed a subtle...'' שמרמז על בעיה", "hostility = עוינות — לא מתאים ל''toward the interests'' שמרמז על נטייה חיובית לתעשייה", "impartiality = חוסר משוא פנים — הפוך מ''betrayed a subtle...'' שמרמז על בעיה", "נכון! bias = הטיה — מתאימה לנטייה נסתרת שמנוגדת למראית עין הניטרלית"]}', 1.91, 2.0, 0.25, 5, 'ai', NULL, true),
('9853caef-89a6-4a92-98ab-49efa4bf65cd', 'restatement', 'The critic''s review, ostensibly balanced, betrayed an unmistakable preference for the director''s earlier, more experimental work.', NULL, '[{"id": "a", "text": "Although appearing balanced, the review clearly revealed a preference for the director''s earlier experimental films."}, {"id": "d", "text": "The director never made any experimental films."}, {"id": "b", "text": "The critic openly stated a preference for the director''s later work."}, {"id": "c", "text": "The review was completely unbiased and showed no preference at all."}]'::jsonb, 0, '{"strategy": "ostensibly balanced, betrayed preference = ניגוד בין מראית עין לגילוי אמיתי.", "correct_reason": "אותה משמעות מדויקת.", "options_analysis": ["נכון! אותה משמעות מדויקת: לכאורה מאוזנת, אך חשפה העדפה ברורה ליצירות הניסיוניות המוקדמות", "הפוך — סותר ''the director''s earlier, more experimental work''", "הפוך — ''ostensibly'' מרמז שההעדפה לא נאמרה בגלוי אלא נחשפה", "הפוך — סותר ''betrayed an unmistakable preference''"]}', 2.31, 2.0, 0.25, 5, 'ai', NULL, true),
('d7ab4620-7cbf-4b6b-8bc3-ae4e6ea8352e', 'restatement', 'The negotiations, ostensibly aimed at de-escalation, in fact allowed both sides to quietly rearm for the next confrontation.', NULL, '[{"id": "a", "text": "The negotiations never took place at all."}, {"id": "c", "text": "Although appearing to aim at reducing tension, the negotiations actually let both sides secretly prepare for future conflict."}, {"id": "b", "text": "Neither side used the negotiations to prepare for anything."}, {"id": "d", "text": "The negotiations genuinely succeeded in achieving lasting de-escalation."}]'::jsonb, 1, '{"strategy": "ostensibly aimed at, in fact allowed = לכאורה נועד ל-, למעשה אפשר. ניגוד.", "correct_reason": "אותה משמעות מדויקת.", "options_analysis": ["סותר את קיום המשא ומתן שתואר", "נכון! אותה משמעות מדויקת: לכאורה להפחתת מתיחות, אך למעשה איפשר התחמשות חשאית", "הפוך — סותר ''allowed both sides to quietly rearm for the next confrontation''", "הפוך — סותר ''in fact allowed both sides to quietly rearm''"]}', 1.93, 2.0, 0.25, 5, 'ai', NULL, true),
('ba09258b-2362-4689-8d1e-87f68444f791', 'restatement', 'The philanthropist''s largesse, though publicly celebrated, was privately viewed by insiders as a calculated bid for a knighthood.', NULL, '[{"id": "a", "text": "Insiders believed the philanthropist''s generosity was entirely selfless."}, {"id": "b", "text": "The philanthropist never received any public recognition."}, {"id": "c", "text": "While praised publicly, the philanthropist''s generosity was seen by insiders as a strategic move to gain a title."}, {"id": "d", "text": "No one had any private opinion about the philanthropist''s motives."}]'::jsonb, 2, '{"strategy": "publicly celebrated, privately viewed as calculated = ניגוד בין תדמית ציבורית לדעה פרטית.", "correct_reason": "אותה משמעות מדויקת.", "options_analysis": ["הפוך — סותר ''a calculated bid for a knighthood''", "סותר ''though publicly celebrated''", "נכון! אותה משמעות מדויקת: פומבית שובחה, אך פנימים ראו בה מהלך אסטרטגי לתואר", "סותר את קיום הדעה הפרטית שתוארה"]}', 1.72, 2.0, 0.25, 5, 'ai', NULL, true),
('a3591209-e6a9-4c81-92f7-bbfb00d30fe9', 'restatement', 'The council''s ruling, though procedurally impeccable, was substantively at odds with the spirit of the original legislation.', NULL, '[{"id": "d", "text": "The ruling both followed procedure and matched the law''s spirit perfectly."}, {"id": "c", "text": "The ruling violated proper procedure but matched the legislation''s spirit perfectly."}, {"id": "a", "text": "No legislation existed for the council to interpret."}, {"id": "b", "text": "Although the ruling followed correct procedure flawlessly, it contradicted the underlying intent of the original law."}]'::jsonb, 3, '{"strategy": "procedurally impeccable, substantively at odds = ניגוד בין הליך לתוכן.", "correct_reason": "אותה משמעות מדויקת.", "options_analysis": ["הפוך — סותר ''substantively at odds with the spirit''", "הפוך — סותר ''procedurally impeccable''", "סותר את קיום החקיקה המקורית שתוארה", "נכון! אותה משמעות מדויקת: הליך תקין לחלוטין, אך סתר את כוונת החוק המקורי"]}', 1.61, 2.0, 0.25, 5, 'ai', NULL, true),
('eb1111fe-a0e3-4baf-ac8a-6830ba2ac8d6', 'restatement', 'The biography''s unflattering portrait, though grounded in meticulous research, was dismissed by the subject''s family as a hatchet job.', NULL, '[{"id": "a", "text": "Despite being based on careful research, the unflattering portrayal was rejected by the family as a malicious attack."}, {"id": "d", "text": "The subject''s family fully endorsed the unflattering portrait."}, {"id": "b", "text": "The biography portrayed its subject in an entirely flattering light."}, {"id": "c", "text": "No research was conducted before writing the biography."}]'::jsonb, 0, '{"strategy": "though grounded in research, dismissed as hatchet job = ניגוד בין ביסוס מחקרי לתגובת המשפחה.", "correct_reason": "אותה משמעות מדויקת.", "options_analysis": ["נכון! אותה משמעות מדויקת: מבוססת על מחקר קפדני, אך המשפחה דחתה כתקיפה זדונית", "הפוך — סותר ''dismissed by the subject''s family as a hatchet job''", "הפוך — ''unflattering'' סותר ''flattering''", "סותר ''grounded in meticulous research''"]}', 1.71, 2.0, 0.25, 5, 'ai', NULL, true),
('1181eccd-eda1-49de-8ecc-83200df24155', 'restatement', 'The startup''s projected growth figures, though impressive on paper, were later revealed to rest on wildly optimistic assumptions.', NULL, '[{"id": "d", "text": "The startup never released any growth projections."}, {"id": "c", "text": "The growth figures were later shown to be based on wildly optimistic, unrealistic assumptions."}, {"id": "b", "text": "The growth figures turned out to be even more conservative than expected."}, {"id": "a", "text": "The growth figures were confirmed to be based on conservative, realistic assumptions."}]'::jsonb, 1, '{"strategy": "impressive on paper, later revealed rest on optimistic assumptions = ניגוד בין מראית עין למציאות.", "correct_reason": "אותה משמעות מדויקת.", "options_analysis": ["סותר את קיום תחזיות הצמיחה שתוארו", "נכון! אותה משמעות מדויקת: מספרים מרשימים על הנייר, אך התבססו על הנחות אופטימיות מדי", "הפוך — סותר ''wildly optimistic assumptions''", "הפוך — ''conservative, realistic'' סותר ''wildly optimistic''"]}', 1.61, 2.0, 0.25, 5, 'ai', NULL, true),
('5d603a22-132b-415c-a893-958c40ee66e1', 'restatement', 'The senator''s concession speech, gracious in tone, nonetheless contained pointed criticism of the electoral process.', NULL, '[{"id": "c", "text": "The concession speech was entirely gracious with no criticism whatsoever."}, {"id": "b", "text": "The speech was harsh in tone and contained no graciousness at all."}, {"id": "d", "text": "Despite its gracious tone, the concession speech included sharp criticism of how the election was conducted."}, {"id": "a", "text": "The senator refused to give any concession speech."}]'::jsonb, 2, '{"strategy": "gracious in tone, nonetheless contained pointed criticism = ניגוד בין טון לתוכן.", "correct_reason": "אותה משמעות מדויקת.", "options_analysis": ["הפוך — סותר ''nonetheless contained pointed criticism''", "הפוך — סותר ''gracious in tone''", "נכון! אותה משמעות מדויקת: טון אדיב, אך כלל ביקורת חדה על תהליך הבחירות", "סותר את קיום נאום הפרישה שתואר"]}', 2.03, 2.0, 0.25, 5, 'ai', NULL, true),
('842df1c8-75e5-46df-8eb2-7b40171a557f', 'restatement', 'The corporation''s internal memo, leaked to the press, revealed a strategy starkly at variance with its public messaging.', NULL, '[{"id": "d", "text": "No memo was ever leaked to the press."}, {"id": "b", "text": "The company never made any public statements about its strategy."}, {"id": "c", "text": "The leaked memo confirmed that the company''s strategy matched its public statements exactly."}, {"id": "a", "text": "The leaked internal memo showed a strategy that sharply contradicted what the company said publicly."}]'::jsonb, 3, '{"strategy": "starkly at variance with public messaging = ניגוד בין אסטרטגיה פנימית להצהרות ציבוריות.", "correct_reason": "אותה משמעות מדויקת.", "options_analysis": ["סותר ''leaked to the press''", "סותר את קיום המסרים הציבוריים שתוארו", "הפוך — סותר ''starkly at variance with its public messaging''", "נכון! אותה משמעות מדויקת: תזכיר פנימי חשף אסטרטגיה שסתרה בחדות את המסרים הציבוריים"]}', 2.05, 2.0, 0.25, 5, 'ai', NULL, true),
('81fc7786-fd10-4fbd-b963-40bc55d16916', 'restatement', 'The judge''s sentencing, though within legal bounds, was perceived by legal scholars as disproportionately lenient given the severity of the crime.', NULL, '[{"id": "a", "text": "Although legally permissible, the sentencing was seen by legal scholars as too lenient considering how serious the crime was."}, {"id": "c", "text": "The sentencing violated all legal boundaries and standards."}, {"id": "d", "text": "Legal scholars considered the sentencing appropriately harsh for the crime''s severity."}, {"id": "b", "text": "No legal scholars ever commented on the sentencing."}]'::jsonb, 0, '{"strategy": "though within legal bounds, perceived as disproportionately lenient = ניגוד בין חוקיות לתפיסה ביקורתית.", "correct_reason": "אותה משמעות מדויקת.", "options_analysis": ["נכון! אותה משמעות מדויקת: חוקית, אך נתפסה כמקלה מדי ביחס לחומרת הפשע", "הפוך — סותר ''though within legal bounds''", "הפוך — סותר ''disproportionately lenient''", "סותר את קיום התגובות המתוארות"]}', 1.99, 2.0, 0.25, 5, 'ai', NULL, true),
('56c49b94-db59-4c17-a9e1-7d9bf0a8eec3', 'restatement', 'The artist''s retrospective, curated with evident affection, nonetheless failed to address the more controversial aspects of her career.', NULL, '[{"id": "b", "text": "The retrospective was curated with obvious hostility toward the artist."}, {"id": "a", "text": "Despite being curated with clear affection, the retrospective did not deal with the more controversial parts of her career."}, {"id": "d", "text": "The retrospective thoroughly addressed every controversial aspect of the artist''s career."}, {"id": "c", "text": "No retrospective of the artist''s work was ever organized."}]'::jsonb, 1, '{"strategy": "curated with affection, nonetheless failed to address controversy = ניגוד בין גישה חיובית לחוסר בשלמות.", "correct_reason": "אותה משמעות מדויקת.", "options_analysis": ["הפוך — ''hostility'' סותר ''evident affection''", "נכון! אותה משמעות מדויקת: אצורה מתוך חיבה, אך לא התייחסה להיבטים השנויים במחלוקת", "הפוך — סותר ''failed to address the more controversial aspects''", "סותר את קיום התערוכה שתוארה"]}', 1.68, 2.0, 0.25, 5, 'ai', NULL, true),
('924ec028-e18c-403b-8b4a-f4d46ea3f959', 'restatement', 'The pharmaceutical company''s disclosure, though technically compliant with regulations, omitted context that critics argued was essential for informed consent.', NULL, '[{"id": "d", "text": "The disclosure violated every applicable regulation."}, {"id": "a", "text": "The disclosure fully included all context critics considered necessary."}, {"id": "c", "text": "While meeting the letter of regulatory requirements, the disclosure left out context that critics said was crucial for informed consent."}, {"id": "b", "text": "No regulations existed governing the company''s disclosures."}]'::jsonb, 2, '{"strategy": "technically compliant, omitted essential context = ניגוד בין ציות טכני לביקורת מהותית.", "correct_reason": "אותה משמעות מדויקת.", "options_analysis": ["הפוך — סותר ''technically compliant with regulations''", "הפוך — סותר ''omitted context that critics argued was essential''", "נכון! אותה משמעות מדויקת: עמדה בדרישות רגולטוריות טכנית, אך השמיטה הקשר חיוני", "סותר את קיום הרגולציה המתוארת"]}', 1.98, 2.0, 0.25, 5, 'ai', NULL, true),
('83d9c435-50e0-4b4e-a810-f95395c2d07b', 'restatement', 'The peace accord, hailed as historic by world leaders, was met with deep skepticism by those living in the conflict zone.', NULL, '[{"id": "c", "text": "People in the conflict zone were the accord''s most enthusiastic supporters."}, {"id": "d", "text": "Both world leaders and local residents viewed the accord with equal enthusiasm."}, {"id": "b", "text": "The peace accord was rejected outright by world leaders."}, {"id": "a", "text": "While praised as historic by international leaders, the accord was regarded with strong doubt by people in the affected region."}]'::jsonb, 3, '{"strategy": "hailed by leaders, met with skepticism by locals = ניגוד בין קבוצות תגובה.", "correct_reason": "אותה משמעות מדויקת.", "options_analysis": ["הפוך — סותר ''met with deep skepticism''", "הפוך — סותר את ההבדל בין תגובות המנהיגים לתושבים", "הפוך — ''rejected outright'' סותר ''hailed as historic''", "נכון! אותה משמעות מדויקת: הוללה ע''י מנהיגי עולם, אך נתקלה בספקנות עמוקה מתושבי האזור"]}', 2.39, 2.0, 0.25, 5, 'ai', NULL, true),
('122c6754-de30-4302-8c7e-03e7f5cce0aa', 'reading_comprehension', 'What is the main purpose of the passage?', 'a4131541-c4d5-4ec5-83fe-a23fa4806145', '[{"id": "a", "text": "To explain the Peter Principle, provide supporting evidence, and note a critique of the idea"}, {"id": "c", "text": "To recommend a specific software tool for tracking employee promotions"}, {"id": "d", "text": "To provide a complete biography of Laurence J. Peter"}, {"id": "b", "text": "To argue that all managers are incompetent at their jobs"}]'::jsonb, 0, '{"strategy": "שאלת מטרה/רעיון מרכזי — הפסקה מסבירה את עקרון פיטר, מציגה ראיות תומכות, ומזכירה ביקורת.", "correct_reason": "הפסקה כוללת הגדרה, מחקר תומך, פתרונות ארגוניים, וביקורת מאוזנת.", "options_analysis": ["נכון! הסבר העיקרון, ראיות תומכות, וביקורת = המטרה המרכזית", "לא מוזכר בפסקה כלל", "לא מוזכר בפסקה כלל — הפסקה עוסקת ברעיון, לא בביוגרפיה", "קיצוני מדי — הפסקה לא טוענת שכל מנהל חסר כשירות"]}', 1.73, 2.0, 0.25, 5, 'ai', NULL, true),
('7c22d054-924e-40fd-94a9-c02004fa3365', 'reading_comprehension', 'According to the passage, what does the Peter Principle claim about promotions in hierarchical organizations?', 'a4131541-c4d5-4ec5-83fe-a23fa4806145', '[{"id": "c", "text": "That promotions are always random and unrelated to performance"}, {"id": "d", "text": "That employees tend to be promoted based on current performance rather than aptitude for the new role, eventually reaching a position for which they are poorly suited"}, {"id": "a", "text": "That no organization has ever promoted an unsuitable employee"}, {"id": "b", "text": "That employees are promoted based on their aptitude for the new role, not their current performance"}]'::jsonb, 1, '{"strategy": "שאלת פרט — חפש את הגדרת עקרון פיטר בפסקה.", "correct_reason": "הפסקה אומרת: ''employees tend to be promoted based on their performance in their current role rather than their aptitude for the role to which they are being promoted...eventually rise to a position for which they are poorly suited''.", "options_analysis": ["לא נאמר בפסקה — העיקרון מתאר תבנית שיטתית, לא אקראיות", "נכון! נאמר במפורש בפסקה", "סותר את כל הפסקה שמתארת בדיוק תופעה כזו", "הפוך גמור ממה שנאמר בפסקה"]}', 1.86, 2.0, 0.25, 5, 'ai', NULL, true),
('4075c968-bfcf-49c5-a5e4-2d265326ce2d', 'reading_comprehension', 'The word "decoupling" in the passage most closely means:', 'a4131541-c4d5-4ec5-83fe-a23fa4806145', '[{"id": "c", "text": "completely destroying"}, {"id": "b", "text": "strongly reinforcing"}, {"id": "a", "text": "separating or disconnecting"}, {"id": "d", "text": "combining tightly together"}]'::jsonb, 2, '{"strategy": "אוצר מילים בהקשר — ''decoupling professional advancement from supervisory responsibility''.", "correct_reason": "decoupling = ניתוק/הפרדה.", "options_analysis": ["לא קשור למשמעות המילה", "הפוך גמור למשמעות המילה", "נכון! decoupling = ניתוק/הפרדה", "הפוך גמור למשמעות המילה"]}', 2.02, 2.0, 0.25, 5, 'ai', NULL, true),
('3785ddae-4bf8-4892-9c6c-567ac9e034b1', 'reading_comprehension', 'According to the passage, what did the study of sales organizations find?', 'a4131541-c4d5-4ec5-83fe-a23fa4806145', '[{"id": "c", "text": "Sales organizations never promote their best salespeople"}, {"id": "b", "text": "Managerial skill and sales skill are always identical"}, {"id": "d", "text": "Promoting top salespeople into management always improved sales performance"}, {"id": "a", "text": "Promoting top salespeople into management often led to declines in overall sales performance"}]'::jsonb, 3, '{"strategy": "שאלת פרט — חפש את ממצא המחקר על ארגוני מכירות בפסקה.", "correct_reason": "הפסקה אומרת: ''firms which promoted their most successful salespeople into managerial roles often experienced a decline in overall sales performance''.", "options_analysis": ["סותר את כל התיאור של המחקר שמתאר קידום כזה", "הפוך — הפסקה מדגישה שמדובר בכישורים שונים לחלוטין", "הפוך גמור ממה שנאמר בפסקה", "נכון! נאמר במפורש בפסקה"]}', 1.82, 2.0, 0.25, 5, 'ai', NULL, true),
('9c04e718-3db5-4f9f-bd74-6ab8607f7e73', 'reading_comprehension', 'What critique of the Peter Principle is mentioned in the passage?', 'a4131541-c4d5-4ec5-83fe-a23fa4806145', '[{"id": "b", "text": "That framing it as a near-universal law overstates the case, since many organizations do consider leadership potential in promotion decisions"}, {"id": "a", "text": "That the principle applies only to sales organizations"}, {"id": "c", "text": "That Laurence J. Peter never conducted any research"}, {"id": "d", "text": "That the phenomenon never actually occurs in any organization"}]'::jsonb, 0, '{"strategy": "שאלת פרט — חפש את הביקורת בסוף הפסקה.", "correct_reason": "הפסקה אומרת: ''framing it as a near-universal law overstates the case, since many organizations do incorporate leadership potential, not merely current performance, into their promotion criteria''.", "options_analysis": ["נכון! נאמר במפורש בפסקה", "סותר את הפסקה שמתארת את העיקרון כתופעה ארגונית כללית", "לא נאמר בפסקה כלל", "הפוך — הביקורת מודה שהתופעה כן קיימת בחלק מהארגונים"]}', 1.74, 2.0, 0.25, 5, 'ai', NULL, true);